    visualizationSuggestions: {zh: "\u5efa\u8b70\u4f7f\u7528\u300c\u8463\u6c0f\u91dd\u7078\u4eba\u9ad4\u5730\u5716\u300d\u4e92\u52d5\u5716\uff0c\u4ee5\u534a\u900f\u660e\u4eba\u9ad4\u8f2a\u5ed3\u70ba\u5e95\u5716\uff0c\u56db\u80a2\u5206\u5e03\u8463\u6c0f\u5341\u90e8\u4f4d\u5947\u7a74\uff0c\u652f\u63f4\u9ede\u64ca\u7a74\u4f4d\u986f\u793a\u540d\u7a31\u3001\u4f4d\u7f6e\u8207\u529f\u6548\u3002\u914d\u4e0a\u8463\u666f\u660c\u5148\u751f\u8096\u50cf\u8207\u4e8b\u8e5f\u6642\u9593\u8ef8\u3002\u53ef\u8a2d\u8a08\u300c\u52d5\u6c23\u91dd\u6cd5\u300d\u52d5\u756b\u793a\u610f\u2014\u2014\u60a3\u8005\u5c0f\u4eba\u8d70\u52d5\u6642\uff0c\u6c23\u7684\u5149\u9ede\u5f9e\u91dd\u523a\u90e8\u4f4d\u6cbf\u80a2\u9ad4\u64f4\u6563\u3002", en: ""}
