    importantPoints: [{name: "\u5e73\u8861\u91dd\u7078", location: "1970\u5e74\u4ee3\u7531\u738b\u6587\u9060\u5275\u7acb\u65bc\u4e2d\u570b\u4eba\u6c11\u89e3\u653e\u8ecd", function: "\u55ae\u7a74\u6cbb\u75c5\u30013\u79d2\u898b\u6548\u3001\u4e09\u79d2\u4e00\u91dd", details: "\u5e73\u8861\u91dd\u7078\u7531\u738b\u6587\u9060\uff081946-\uff09\u5275\u7acb\uff0c\u4ee5\u4e2d\u91ab\u9670\u967d\u6574\u9ad4\u5b78\u8aaa\u8207\u897f\u91ab\u795e\u7d93\u8abf\u63a7\u5b78\u8aaa\u76f8\u7d50\u5408\u70ba\u7406\u8ad6\u6838\u5fc3\u3002\u6838\u5fc3\u7406\u8ad6\u662f\u5927\u8166\u4e2d\u6a1e\u795e\u7d93\u8abf\u63a7\u8ad6\u2014\u2014\u8a8d\u70ba\u91dd\u523a\u4fe1\u865f\u901a\u904e\u795e\u7d93\u4e0a\u50b3\u81f3\u5927\u8166\u9ad8\u7d1a\u4e2d\u6a1e\uff0c\u555f\u52d5\u81ea\u6211\u5e73\u8861\u4fee\u5fa9\u6a5f\u5236\u3002\u53d6\u7a74\u7279\u9ede\u662f\u300c\u55ae\u7a74\u300d\u2014\u2014\u901a\u5e38\u53ea\u53d6\u4e00\u500b\u7a74\u4f4d\u5373\u53ef\u6cbb\u7642\u5168\u8eab\u5404\u7cfb\u7d71\u75be\u75c5\u3002\u7a81\u51fa\u300c3\u79d2\u9418\u300d\u7684\u6982\u5ff5\uff1a\u9032\u91dd\u5feb\uff081\u79d2\uff09\u3001\u51fa\u91dd\u5feb\uff081\u79d2\uff09\u3001\u7559\u91dd1\u79d2\u5f8c\u5373\u53ef\u51fa\u91dd\u3002\u4ee3\u8868\u7a74\uff1a\u8170\u75db\u7a74\uff08\u984d\u6b63\u4e2d\uff09\u3001\u80a9\u75db\u7a74\uff08\u8e1d\u95dc\u7bc0\uff09\u3001\u9838\u75db\u7a74\uff08\u624b\u80cc\uff09\u3002"},{name: "\u539f\u59cb\u9ede", location: "2002\u5e74\u7531\u5f35\u91d7\u6f22\u5728\u53f0\u7063\u5275\u7acb", function: "\u4ee5\u4e00\u689d\u810a\u690e\uff08\u9838\u3001\u80f8\u3001\u8170\u3001\u85a6\u690e\uff09+\u4e03\u8655\u539f\u59cb\u9ede\u8986\u84cb\u5168\u8eab", details: "\u539f\u59cb\u9ede\u7642\u6cd5\u7531\u5f35\u91d7\u6f22\uff081958-\uff09\u5728\u53f0\u7063\u5275\u7acb\uff0c\u7406\u8ad6\u8a8d\u70ba\u6240\u6709\u75be\u75c5\u75c7\u72c0\u90fd\u6e90\u65bc\u300c\u4ed6\u8655\u7b4b\u50b7\u300d\uff08\u5373\u808c\u8089\u3001\u7b4b\u819c\u3001\u97cc\u5e36\u7b49\u8edf\u7d44\u7e54\u7684\u640d\u50b7\uff09\uff0c\u6cbb\u7642\u4ee5\u6309\u63c9\uff08\u4e0d\u4f7f\u7528\u91dd\uff09\u70ba\u4e3b\uff0c\u7a31\u70ba\u300c\u539f\u59cb\u9ede\u300d\u3002\u4e00\u689d\u810a\u690e\uff08\u5f9e\u982d\u90e8\u5f8c\u5074\u7e5e\u81f3\u524d\u9762\uff0c\u518d\u6cbf\u80cc\u90e8\u81f3\u5c3e\u690e\uff09\u52a0\u4e03\u8655\u539f\u59cb\u9ede\uff08\u982d\u90e8\u3001\u80a9\u90e8\u3001\u814b\u4e0b\u3001\u8098\u90e8\u3001\u624b\u80cc\u90e8\u3001\u81c0\u90e8\u3001\u8e1d\u53ca\u8db3\u5e95\u90e8\uff09\u5373\u53ef\u8986\u84cb\u5168\u8eab\u3002\u81e8\u5e8a\u4e0a\u5c0d\u6162\u6027\u75bc\u75db\u3001\u5167\u79d1\u75be\u75c5\u5eb7\u5fa9\u6709\u986f\u8457\u6548\u679c\u3002"},{name: "\u6d6e\u91dd", location: "1996\u5e74\u7531\u7b26\u4ef2\u83ef\u5728\u4e2d\u570b\u5927\u9678\u9996\u5275", function: "\u4f5c\u7528\u65bc\u6dfa\u7b4b\u819c\u5c64\uff0c\u6cbb\u7642\u808c\u7b4b\u819c\u75bc\u75db\u7d9c\u5408\u5fb5", details: "\u6d6e\u91dd\u7531\u7b26\u4ef2\u83ef\uff081965-\uff09\u767c\u660e\uff0c\u662f\u4e00\u7a2e\u65b0\u578b\u91dd\u523a\u5de5\u5177\u8207\u6280\u6cd5\u3002\u63a1\u7528\u5c08\u7528\u300c\u6d6e\u91dd\u91dd\u5177\u300d\uff0c\u64cd\u4f5c\u6642\u5c07\u91dd\u9ad4\u6c34\u5e73\u63a8\u9032\u76ae\u4e0b\u758f\u9b06\u7d50\u7de0\u7d44\u7e54\u5c64\uff08\u6dfa\u7b4b\u819c\uff09\uff0c\u7136\u5f8c\u9032\u884c\u300c\u6383\u6563\u300d\u52d5\u4f5c\uff0c\u4f7f\u91dd\u9ad4\u5728\u76ae\u4e0b\u4f86\u56de\u5e73\u79fb\u3002\u7406\u8ad6\u57fa\u790e\u662f\u300c\u6383\u6563\u53ef\u4ee5\u91cd\u65b0\u8abf\u6574\u60a3\u8655\u7684\u751f\u7269\u5f35\u529b\u7d50\u69cb\u300d\uff0c\u901a\u904e\u6539\u8b8a\u7b4b\u819c\u7684\u529b\u5b78\u72c0\u614b\u800c\u7de9\u89e3\u75bc\u75db\u3002\u512a\u9ede\u662f\u60a3\u8005\u5e7e\u4e4e\u5b8c\u5168\u7121\u75db\u611f\uff0c\u5c0d\u8170\u80cc\u7b4b\u819c\u708e\u3001\u80a9\u5468\u708e\u3001\u9838\u690e\u75c5\u3001\u7db2\u7403\u8098\u7b49\u808c\u7b4b\u819c\u75bc\u75db\u7642\u6548\u8fc5\u901f\u986f\u8457\u3002"},{name: "\u4e7e\u91dd\uff08Dry Needling\uff09", location: "\u897f\u65b9\u5eb7\u5fa9\u91ab\u5b78\u754c\uff0c1940\u5e74\u4ee3\u958b\u59cb\u767c\u5c55", function: "\u897f\u65b9\u7269\u7406\u6cbb\u7642\u5e2b\u3001\u6574\u810a\u5e2b\u4f7f\u7528\uff0c\u4ee5\u6fc0\u75db\u9ede\u7406\u8ad6\u70ba\u57fa\u790e", details: "\u4e7e\u91dd\u662f\u897f\u65b9\u91ab\u7642\u5f9e\u696d\u8005\uff08\u7269\u7406\u6cbb\u7642\u5e2b\u3001\u6574\u810a\u5e2b\u7b49\uff09\u767c\u5c55\u7684\u91dd\u523a\u6280\u8853\uff0c\u7406\u8ad6\u57fa\u790e\u6e90\u81eaJanet Travell\u7684\u300c\u6fc0\u75db\u9ede\uff08Myofascial Trigger Points, MTrPs\uff09\u5b78\u8aaa\u300d\u3002\u8a8d\u70ba\u808c\u8089\u7dca\u7e2e\u5e36\u4e2d\u7684\u6fc0\u75db\u9ede\u662f\u75bc\u75db\u7684\u6839\u6e90\uff0c\u7d30\u91dd\u7a7f\u523a\uff08\u4e0d\u6ce8\u5c04\u4efb\u4f55\u85e5\u7269\uff0c\u6545\u7a31\u300c\u4e7e\u300d\uff09\u53ef\u6ec5\u6d3b\u6fc0\u75db\u9ede\u3001\u6062\u5fa9\u808c\u8089\u6b63\u5e38\u5f35\u529b\u3002\u8207\u50b3\u7d71\u4e2d\u91ab\u91dd\u7078\u7684\u5340\u5225\uff1a\u5b8c\u5168\u57fa\u65bc\u897f\u91ab\u89e3\u5256\u5b78\uff0c\u4e0d\u7528\u4e2d\u91ab\u7d93\u7d61\u7406\u8ad6\uff0c\u53d6\u7a74\u4f9d\u64da\u808c\u8089\u89e3\u5256\u4f4d\u7f6e\u3002\u8fd120\u5e74\u5728\u6b50\u7f8e\u5feb\u901f\u666e\u53ca\uff0c\u7f8e\u570b\u5927\u591a\u6578\u5dde\u5df2\u5408\u6cd5\u5316\u3002"},{name: "\u91dd\u5200", location: "1976\u5e74\u7531\u6731\u6f22\u7ae0\u5728\u4e2d\u570b\u9996\u5275", function: "\u7d50\u5408\u91dd\u7078\u91dd\u5c16\u90e8\u8207\u624b\u8853\u5200\u529f\u80fd\uff0c\u6cbb\u7642\u8edf\u7d44\u7e54\u7c98\u9023\u8207\u6523\u7e2e", details: "\u91dd\u5200\u7531\u6731\u6f22\u7ae0\uff081949-\uff09\u767c\u660e\uff0c\u7d50\u5408\u4e86\u50b3\u7d71\u9577\u91dd\u7684\u91dd\u523a\u611f\u8207\u624b\u8853\u5200\u7684\u5207\u5272\u529f\u80fd\u3002\u91dd\u5200\u5916\u5f62\u4f3c\u91dd\u4f46\u5c16\u7aef\u70ba\u6241\u5e73\u7684\u300c\u5200\u5203\u300d\uff08\u5bec\u5ea60.8-1.5mm\uff09\uff0c\u53ef\u7528\u65bc\u8edf\u7d44\u7e54\u7684\u5fae\u5275\u5207\u5272\u3001\u5206\u96e2\u7c98\u9023\u3001\u9b06\u89e3\u6523\u7e2e\u3002\u9069\u61c9\u75c7\u4e3b\u8981\u662f\uff1a\u8171\u9798\u708e\uff08\u6273\u6a5f\u6307\uff09\u3001\u80a9\u5468\u708e\u7c98\u9023\u3001\u819d\u95dc\u7bc0\u6523\u7e2e\u3001\u8db3\u5e95\u7b4b\u819c\u708e\u3001\u9838\u690e\u75c5\u7b49\u8edf\u7d44\u7e54\u7591\u96e3\u96dc\u75c7\u3002\u7406\u8ad6\u57fa\u790e\u662f\u4e2d\u91ab\u7684\u300c\u7d93\u7b4b\u75c5\u300d\u5b78\u8aaa\u7d50\u5408\u897f\u91ab\u8edf\u7d44\u7e54\u5916\u79d1\u5b78\u3002\u64cd\u4f5c\u9700\u5177\u5099\u89e3\u5256\u5b78\u77e5\u8b58\u3002"}],
    visualizationSuggestions: {zh: "\u5efa\u8b70\u4f7f\u7528\u300c\u91dd\u6cd5\u539f\u7406\u5c0d\u6bd4\u96f7\u9054\u5716\u300d\uff0c\u4ee5\u4e94\u908a\u5f62\u96f7\u9054\u5716\u5c55\u793a\u4e94\u7a2e\u65b0\u8208\u7642\u6cd5\u5728\u3010\u7406\u8ad6\u5275\u65b0\u7a0b\u5ea6\u3011\u3010\u897f\u91ab\u7d50\u5408\u5ea6\u3011\u3010\u50b3\u7d71\u7d93\u7d61\u4f9d\u8cf4\u5ea6\u3011\u3010\u64cd\u4f5c\u6a19\u6e96\u5316\u7a0b\u5ea6\u3011\u3010\u60a3\u8005\u8212\u9069\u5ea6\u3011\u4e94\u500b\u7dad\u5ea6\u4e0a\u7684\u8868\u73fe\u5dee\u7570\u3002\u6bcf\u500b\u5b78\u6d3e\u7528\u4e0d\u540c\u984f\u8272\u586b\u5145\uff0c\u53ef\u76f4\u89c0\u770b\u51fa\u5404\u81ea\u7279\u9ede\u3002\u914d\u5408\u6bcf\u500b\u5b78\u6d3e\u7684\u624b\u6cd5\u548c\u5de5\u5177\u793a\u610f\u5716\uff0c\u5f62\u6210\u5b8c\u6574\u7684\u8996\u89ba\u767e\u79d1\u3002", en: ""}
